#!/usr/bin/env python3
"""run_mmu_exp.py [-v] [name...] : the MMU programs of ~/vhdl/63F09/regress/asm (mmuA*, mmuB*, mmuC*, generated by proto/mmu_test/gen_mmu2.py) on the
simulator, against their .exp files (values of the Python model of the MMU, checked against the VHDL simulation).

  Copyright (C) 2026 Dr. BERTRAND Joël, Claude

A line "i vv" of a .exp is the byte at $FFFC4000 + i, a line "D i vv" the byte at $FFFC1000 + i (same rule as regress/mmu_cmp.py : a value never written
that the model gives as 00 or FF is not compared).
"""
import json, os, subprocess, sys, tempfile

HERE = os.path.dirname(os.path.abspath(__file__))
SIM = os.path.join(HERE, '..', '..', 'BIN', 'm63f09')
A09 = os.path.expanduser('~/cvs/gcc/binutils-gdb/test/a09_reference/a09')
CONV = os.path.join(HERE, '..', 'tools', 's09_to_elf.py')
REG = os.path.expanduser('~/vhdl/63F09/regress')
verbose = '-v' in sys.argv
names = [a for a in sys.argv[1:] if not a.startswith('-')]

tests = []
for f in ('tests_mmu.json', 'tests_mmuc.json'):
    tests += [t['name'] for t in json.load(open(os.path.join(REG, f)))]
bad = 0
for name in tests:
    if names and name not in names:
        continue
    exp = os.path.join(REG, 'asm', name + '.exp')
    if not os.path.exists(exp):
        continue
    tmp = tempfile.mkdtemp()
    src = os.path.join(REG, 'asm', name + '.asm')
    subprocess.run(['cp', '-f', src, os.path.join(tmp, 'p.asm')])
    subprocess.run([A09, '-oF09', '-S', 'p.asm'], cwd=tmp, capture_output=True)
    if not os.path.exists(os.path.join(tmp, 'p.s09')):
        print('%-8s a09 failed' % name); bad += 1; continue
    subprocess.run(['python3', CONV, os.path.join(tmp, 'p.s09'), os.path.join(tmp, 'p.elf')], capture_output=True)
    o1, o2 = os.path.join(tmp, 'r1.bin'), os.path.join(tmp, 'r4.bin')
    open(os.path.join(tmp, 's.ini'), 'w').write('set cpu extmem=1\nload %s/p.elf\nreset\ngo\ndump %s FFFFC1000-FFFFC1FFF\ndump %s FFFFC4000-FFFFC43FF\n' % (tmp, o1, o2))
    r = subprocess.run([SIM, os.path.join(tmp, 's.ini')], capture_output=True, text=True, stdin=subprocess.DEVNULL, timeout=600)
    m1 = open(o1, 'rb').read() if os.path.exists(o1) else b''
    m4 = open(o2, 'rb').read() if os.path.exists(o2) else b''
    wrong = tot = 0
    first = []
    for l in open(exp):
        f = l.split()
        if f[0] == 'D':
            i, v, mem = int(f[1]), int(f[2], 16), m1
        else:
            i, v, mem = int(f[0]), int(f[1], 16), m4
        tot += 1
        got = mem[i] if i < len(mem) else None
        if got is None or (got == 0 and v in (0, 0xFF)):
            if got is None:
                wrong += 1
            continue
        if got != v:
            wrong += 1
            if len(first) < 4:
                first.append('%s %d: got %02x want %02x' % ('D' if f[0] == 'D' else 'R', i, got, v))
    stop = [l for l in r.stdout.splitlines() if 'stop' in l.lower() or 'Branch' in l]
    print('%-8s %d values, %d wrong %s %s' % (name, tot, wrong, '; '.join(first), (stop[-1] if verbose and stop else '')))
    bad += 1 if wrong else 0
sys.exit(1 if bad else 0)
